import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const [loading, setLoading] = useState(false);
    const [requests, setRequests] = useState([]);
    const [filterRoom, setFilterRoom] = useState(''); // Thêm tính năng lọc theo phòng nếu cần

    // --- PHẦN KẾT NỐI BACKEND (Giao diện sẵn sàng cho API) ---
    useEffect(() => {
        const fetchRequests = async () => {
            setLoading(true);
            try {
                // SAU NÀY: const res = await axios.get('http://localhost:5000/api/maintenance');
                // setRequests(res.data);

                // GIẢ LẬP DỮ LIỆU TỪ DATABASE
                setTimeout(() => {
                    setRequests([
                        { id: 1, room: 'A101', issue: 'Hỏng vòi nước bồn rửa mặt', date: '16/04/2026', status: 'pending' },
                        { id: 2, room: 'B202', issue: 'Cháy bóng đèn hành lang tầng 2', date: '15/04/2026', status: 'processing' },
                        { id: 3, room: 'C501', issue: 'Máy lạnh phát ra tiếng kêu to', date: '14/04/2026', status: 'completed' },
                        { id: 4, room: 'D905', issue: 'Cửa ban công bị kẹt khóa', date: '13/04/2026', status: 'pending' },
                    ]);
                    setLoading(false);
                }, 500);
            } catch (error) {
                console.error("Lỗi lấy dữ liệu:", error);
                setLoading(false);
            }
        };
        fetchRequests();
    }, []);

    // HÀM CẬP NHẬT TRẠNG THÁI (Đã tối ưu cho Backend)
    const updateStatus = async (id, newStatus) => {
        // 1. Cập nhật UI lập tức (Optimistic Update)
        setRequests(prev => prev.map(req => req.id === id ? { ...req, status: newStatus } : req));

        // 2. GỬI LÊN SERVER
        try {
            // await axios.put(`http://localhost:5000/api/maintenance/${id}`, { status: newStatus });
            console.log(`Backend: Đã cập nhật ID ${id} thành ${newStatus}`);
        } catch (error) {
            alert("Không thể cập nhật trạng thái, vui lòng thử lại!");
        }
    };

    // Định nghĩa màu sắc cho từng trạng thái
    const getStatusStyle = (status) => {
        switch (status) {
            case 'pending': return { label: 'Chờ xử lý', color: '#dc3545', bg: '#f8d7da', border: '#f5c6cb' };
            case 'processing': return { label: 'Đang xử lý', color: '#856404', bg: '#fff3cd', border: '#ffeeba' };
            case 'completed': return { label: 'Hoàn thành', color: '#155724', bg: '#d4edda', border: '#c3e6cb' };
            default: return { label: 'Khác', color: '#383d41', bg: '#e2e3e5', border: '#d6d8db' };
        }
    };

    // Lọc danh sách nếu bạn nhập số phòng vào ô tìm kiếm
    const filteredRequests = requests.filter(req => 
        req.room.toLowerCase().includes(filterRoom.toLowerCase())
    );

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', height: 'calc(100vh - 120px)',
            boxShadow: '0 10px 40px rgba(0,0,0,0.4)', position: 'relative'
        }} className="glass-card">

            {/* Header đồng bộ với các module khác */}
            <div style={{ 
                padding: '20px 30px', background: 'rgba(0,0,0,0.4)', 
                display: 'flex', justifyContent: 'space-between', alignItems: 'center',
                backdropFilter: 'blur(10px)', borderBottom: '1px solid rgba(255,255,255,0.1)'
            }}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '24px', fontWeight: 'bold' }}>
                    🛠 QUẢN LÝ YÊU CẦU BẢO TRÌ
                </h2>
                <div style={{ display: 'flex', gap: '15px' }}>
                    <input 
                        type="text" 
                        placeholder="Tìm theo số phòng..." 
                        value={filterRoom}
                        onChange={(e) => setFilterRoom(e.target.value)}
                        style={{
                            padding: '10px 15px', borderRadius: '15px', border: 'none',
                            outline: 'none', width: '200px', backgroundColor: 'rgba(255,255,255,0.9)'
                        }}
                    />
                </div>
            </div>

            {/* Vùng hiển thị nội dung */}
            <div style={{ flex: 1, padding: '25px', display: 'flex', justifyContent: 'center', overflow: 'hidden' }}>
                <div style={{ 
                    width: '100%', maxWidth: '1100px', backgroundColor: 'rgba(255, 255, 255, 0.95)', 
                    borderRadius: '25px', display: 'flex', flexDirection: 'column',
                    boxShadow: '0 8px 32px rgba(0,0,0,0.3)', overflow: 'hidden'
                }}>

                    <div style={{ flex: 1, overflowY: 'auto' }} className="custom-scrollbar">
                        {loading ? (
                            <div style={{ textAlign: 'center', padding: '100px', fontSize: '20px', color: '#8b5e5e', fontWeight: 'bold' }}>
                                ĐANG TRUY XUẤT YÊU CẦU...
                            </div>
                        ) : filteredRequests.length > 0 ? (
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead style={{ position: 'sticky', top: 0, backgroundColor: '#f8f9fa', zIndex: 10 }}>
                                    <tr style={{ textAlign: 'left', borderBottom: '2px solid #dee2e6' }}>
                                        <th style={{ padding: '20px', color: '#444' }}>PHÒNG</th>
                                        <th style={{ padding: '20px', color: '#444' }}>NỘI DUNG SỰ CỐ</th>
                                        <th style={{ padding: '20px', color: '#444' }}>NGÀY GỬI</th>
                                        <th style={{ padding: '20px', color: '#444' }}>TRẠNG THÁI</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredRequests.map((req) => {
                                        const style = getStatusStyle(req.status);
                                        return (
                                            <tr key={req.id} style={{ borderBottom: '1px solid #eee', transition: '0.3s' }} className="row-hover">
                                                <td style={{ padding: '20px', fontWeight: '800', fontSize: '20px', color: '#333' }}>
                                                    {req.room}
                                                </td>
                                                <td style={{ padding: '20px', color: '#555', fontSize: '15px', lineHeight: '1.4' }}>
                                                    {req.issue}
                                                </td>
                                                <td style={{ padding: '20px', color: '#888', fontSize: '14px' }}>
                                                    {req.date}
                                                </td>
                                                <td style={{ padding: '20px' }}>
                                                    <select 
                                                        value={req.status} 
                                                        onChange={(e) => updateStatus(req.id, e.target.value)}
                                                        style={{ 
                                                            padding: '10px 15px', borderRadius: '12px', border: `1px solid ${style.border}`,
                                                            backgroundColor: style.bg, color: style.color,
                                                            fontWeight: 'bold', cursor: 'pointer', outline: 'none',
                                                            fontSize: '14px', width: '150px'
                                                        }}
                                                    >
                                                        <option value="pending">⏳ Chờ xử lý</option>
                                                        <option value="processing">🛠 Đang xử lý</option>
                                                        <option value="completed">✅ Hoàn thành</option>
                                                    </select>
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        ) : (
                            <div style={{ textAlign: 'center', padding: '100px', color: '#999' }}>
                                <div style={{ fontSize: '50px' }}>📁</div>
                                <p>Không có yêu cầu bảo trì nào được tìm thấy.</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Style CSS bổ sung */}
            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                .row-hover:hover { background-color: #fcfcfc; }
                .glass-card { backdrop-filter: blur(5px); }
            `}</style>
        </div>
    );
};

export default QuanLyBaoTri;
